JOB DESCRIPTION:
{{ $json.jobDescription }}

CANDIDATE CONTEXT:
{{ $json.candidateContext }}

options.systemMessage:
You are ResumeForge, an expert ATS-optimized resume writer.

You receive the target job description and the candidate's structured profile data (work experience, education, GitHub profile & repos, portfolio). Build an optimized resume for the target role.

OUTPUT RULES:
1. Reply with ONLY one valid JSON object. No markdown, no code fences, no commentary.
2. The JSON must match EXACTLY this schema:
{
  "resume": {
    "name": "string",
    "title": "string",
    "summary": "string",
    "skills": ["string"],
    "experience": [
      { "company": "string", "role": "string", "duration": "string", "highlights": ["string"] }
    ],
    "projects": [
      { "name": "string", "description": "string", "highlights": ["string"], "tech": ["string"] }
    ],
    "education": [
      { "institution": "string", "degree": "string", "year": "string" }
    ]
  }
}
3. Treat sections marked "PRIMARY SOURCE" in the candidate data as ground truth. Never invent or change companies, roles, dates, or listed achievements.
4. Weave relevant job-description keywords into the summary, skills, and highlights naturally. No keyword stuffing.
5. Quantify achievements whenever possible (percentages, dollars, time saved, users, scale).
6. Keep 3-6 highlights per role, 3-5 projects, 6-10 skills.
7. If a value is unknown, use "" for strings and [] for arrays. Never invent identity details; default the name to "Your Name".
8. Escapes double quotes inside strings properly. Return valid JSON only.

parameters.jsCode:
// ---- 1. Extract raw LLM text (AI Agent returns { output: string }) ----
const raw =
  $json.output ??
  $json.message?.content ??
  $json.choices?.[0]?.message?.content ??
  $json.result ??
  $json.raw ??
  "";

function cleanJson(text) {
  if (!text || typeof text !== "string") return null;
  let t = text.trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) t = fence[1].trim();
  const start = t.indexOf("{");
  const end = t.lastIndexOf("}");
  if (start === -1 || end === -1 || end <= start) return null;
  try { return JSON.parse(t.slice(start, end + 1)); } catch (e) { return null; }
}

const parsed = cleanJson(raw);
const ai = parsed && parsed.resume ? parsed : parsed ? { resume: parsed } : null;

function asString(v, fallback = "") { return v == null ? fallback : String(v); }
function asArray(v) {
  if (Array.isArray(v)) return v.filter((x) => x != null);
  if (typeof v === "string" && v.trim()) return v.split(",").map((s) => s.trim()).filter(Boolean);
  return [];
}
function asStrings(v) { return asArray(v).map((x) => asString(x)); }

// ---- 2. Early error if the AI produced nothing usable ----
if (!ai) {
  return [{ json: { success: false, error: "AI returned an empty or invalid response. Please try again." } }];
}

// ---- 3. Normalize resume to exactly match ResumeSchema ----
const resume = {
  name: asString(ai.resume?.name, "Your Name"),
  title: asString(ai.resume?.title, "Professional"),
  summary: asString(ai.resume?.summary, ""),
  skills: asStrings(ai.resume?.skills).slice(0, 20),
  experience: asArray(ai.resume?.experience).map((e) => ({
    company: asString(e.company, "Unknown Company"),
    role: asString(e.role, "Role"),
    duration: asString(e.duration, ""),
    highlights: asStrings(e.highlights),
  })),
  projects: asArray(ai.resume?.projects).map((p) => ({
    name: asString(p.name, "Project"),
    description: asString(p.description, ""),
    highlights: asStrings(p.highlights),
    tech: asStrings(p.tech),
  })),
  education: asArray(ai.resume?.education).map((e) => ({
    institution: asString(e.institution, "Institution"),
    degree: asString(e.degree, "Degree"),
    year: asString(e.year, ""),
  })),
};

// ---- 4. Deterministic score (0-100) against the job description ----
const jobDescription = asString($("Webhook").first().json?.jobDescription);
const resumeLower = JSON.stringify(resume).toLowerCase();

const stopWords = new Set([
  "the","a","an","and","or","but","for","with","in","on","at","to","of","is","are","as","by","be","been","being","have","has","had","we","our","you","your","they","their","this","that","these","those","will","would","can","could","should","must","may","might","do","does","did","from","into","over","under","between","within","across","about","than","then","also","very","just","not","no","yes","all","any","both","each","few","many","much","more","most","some","such","work","job","role","position","company","candidate","resume","experience","year","years","using","use","used","include","including","strong","solid","proven","ability","abilities","skills","skill","etc","e.g","team","environment","looking","seek","seeking","opportunity","responsibilities","requirements","qualifications","preferred","nice","plus","what","who","whom","which","when","where","why","how","it","its","he","she","him","her","them"
]);

const words = jobDescription
  .toLowerCase()
  .replace(/[^a-z0-9+#.\-]/g, " ")
  .split(/\s+/)
  .filter((w) => w.length > 2 && !/^\d+$/.test(w) && !stopWords.has(w));
const keywords = [...new Set(words)];

const keywordMatch = keywords.length
  ? Math.round((keywords.filter((k) => resumeLower.includes(k)).length / keywords.length) * 100)
  : 50;

const skillSet = new Set(resume.skills.map((s) => s.toLowerCase()));
const skillMatches = keywords.filter((k) =>
  [...skillSet].some((s) => s === k || s.includes(k) || k.includes(s))
);
const skillsMatch = keywords.length
  ? Math.round((skillMatches.length / keywords.length) * 100)
  : 50;

const actionVerbs = [
  "built","developed","created","designed","implemented","managed","led","improved",
  "increased","reduced","optimized","launched","shipped","collaborated","engineered",
  "architected","maintained","delivered","deployed","automated","spearheaded",
  "established","streamlined","mentored","trained","analyzed","researched","integrated",
  "migrated","scaled","boosted","grew","drove","initiated","rebuilt","refactored",
];
const highlightText = resume.experience.flatMap((e) => e.highlights).join(" ").toLowerCase();
const verbCount = actionVerbs.filter((v) => highlightText.includes(v)).length;
const experienceMatch = Math.min(
  95,
  resume.experience.length >= 2 ? 50 + verbCount * 5 : 35 + verbCount * 3
);

const clamp = (n) => Math.min(100, Math.max(0, Math.round(n)));
const score = {
  overall: clamp(skillsMatch * 0.35 + keywordMatch * 0.3 + experienceMatch * 0.35),
  skillsMatch: clamp(skillsMatch),
  experienceMatch: clamp(experienceMatch),
  keywordMatch: clamp(keywordMatch),
};

return [{ json: { success: true, resume, score } }];
